
from pathlib import Path

import joblib
import pandas as pd

# Locate the saved model
PROJECT_ROOT = Path(__file__).resolve().parent
MODEL_PATH = PROJECT_ROOT / "saved_models" / "diabetes_model.joblib"


def load_model():
    if not MODEL_PATH.exists():
        raise FileNotFoundError(
            "Model not found. Run 'python -m src.train' first."
        )

    # Load only model files generated by your trusted training code
    saved = joblib.load(MODEL_PATH)

    return saved["model"], saved["features"]


def predict_diabetes(health_data):
    model, features = load_model()

    # Check that all required inputs are provided
    missing = [feature for feature in features if feature not in health_data]
    extra = [feature for feature in health_data if feature not in features]

    if missing or extra:
        raise ValueError(
            f"Missing features: {missing}\n"
            f"Unexpected features: {extra}"
        )

    # Preserve the feature order used during training
    input_data = pd.DataFrame(
        [{feature: health_data[feature] for feature in features}]
    )

    prediction = int(model.predict(input_data)[0])

    result = {
        "prediction": prediction,
        "classification": (
            "Higher diabetes risk"
            if prediction == 1
            else "Lower diabetes risk"
        )
    }

    if hasattr(model, "predict_proba"):
        result["model_score"] = float(
            model.predict_proba(input_data)[0][1]
        )

    return result


if __name__ == "__main__":
    model, features = load_model()

    print("Model loaded successfully!")
    print(f"Number of required features: {len(features)}")
    print("\nRequired features:")

    for feature in features:
        print(f"- {feature}")
